import {FieldHardware} from './field-hardware.js?v=20261029-ipad-1';
import {CONDITIONS,stableReading,clinometer,conditionReview,validateInstrument,parseObservations} from './field-core.js?v=20261029-ipad-1';
const KEY='danan-field-observations-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number.isFinite(n)?n.toFixed(2):'—';
export function mountField(root,{onUse,toast,ask,plants,selectedId}){
 const $=s=>root.querySelector(s),env={DeviceOrientationEvent:window.DeviceOrientationEvent,isSecureContext:window.isSecureContext,mediaDevices:navigator.mediaDevices,addEventListener:(...a)=>window.addEventListener(...a),removeEventListener:(...a)=>window.removeEventListener(...a),setTimeout:(fn,ms)=>window.setTimeout(fn,ms),clearTimeout:id=>window.clearTimeout(id),now:Date.now};
 const hardware=new FieldHardware(env);let zero=null,locked=null,photo=null,photoUrl=null,observations=[],storageError=false,disposed=false;
 try{const raw=localStorage.getItem(KEY);if(raw)observations=parseObservations(raw);}catch{storageError=true;}
 root.innerHTML=`<div class="section-head"><div><p class="eyebrow">IPAD / FIELD NOTEBOOK</p><h1>把 iPad 變成量樹小幫手</h1><p class="muted">後鏡頭瞄準＋姿態感測器量仰角。距離、胸圍與樹形仍需現場測量與確認。</p></div><span class="badge orange">輔助估算・非 CO₂ 偵測器</span></div><div class="workbench"><div><div class="field-camera"><video id="field-video" playsinline muted aria-label="後鏡頭預覽"></video><div class="camera-placeholder" id="camera-placeholder"><span>⌖</span>讓畫面中心瞄準樹梢<p>相機預設關閉；影像不會傳到網路。</p></div><div class="crosshair" aria-hidden="true">＋</div><div class="angle-pill"><span id="angle-kind">即時仰角</span> <strong id="live-angle">—</strong> °</div></div><div class="tools"><button id="camera-start">開啟後鏡頭</button><button id="camera-stop">關閉鏡頭</button><button id="take-photo">拍照留證</button><label class="file-button">選擇／拍攝照片<input id="photo-input" type="file" accept="image/jpeg,image/png,image/webp" capture="environment"></label></div><p id="camera-status" class="hint" role="status">未使用相機。可以不開相機，用安全觀測器輔助瞄準。</p><div id="photo-area" hidden><img id="photo-preview" alt="本機現地樹形照片"><div class="row"><button id="photo-download">下載照片</button><button id="photo-remove">移除照片預覽</button></div><p class="hint">照片只暫存於本頁記憶體。離頁即移除，請自行下載。系統不會分析照片或自動辨識分岔。</p></div><section class="panel"><h2>樹形檢查・先看清楚，再估算</h2><p class="hint">請目視或查看照片，勾選實際狀況。這是人工檢核，系統只依勾選內容自動提醒。</p><label class="check"><input id="inspected" type="checkbox">已檢查根部到胸高與樹冠，能確認樹形</label><div class="condition-grid">${Object.entries(CONDITIONS).map(([key,c])=>`<label class="check"><input type="checkbox" name="condition" value="${key}">${c.label}</label>`).join('')}</div><label>胸圍實際測點離地高度（m）<input id="measurement-height" type="number" min="0.1" max="10" step="0.01" value="1.3"></label><label>校樹對照（選填）<select id="field-tree"><option value="">尚未對照平台校樹</option>${plants.map(p=>`<option value="${esc(p.id)}">${esc(p.label+'｜'+p.species)}</option>`).join('')}</select></label><label>樹名／編號（現勘紀錄用）<input id="observation-name" maxlength="100" placeholder="例如：T016 樟樹"></label><label>觀察備註<textarea id="condition-notes" rows="3" maxlength="1500" placeholder="分岔高度、測點位置、看不清楚的地方…"></textarea></label><div id="condition-feedback" class="note" role="status"></div><div class="tools"><button id="save-observation">儲存現勘紀錄</button><button id="export-observations">匯出現勘 JSON ↓</button><label class="file-button">匯入現勘 JSON<input id="import-observations" type="file" accept=".json,application/json"></label><button id="clear-observations" class="danger">清除現勘紀錄</button><button id="export-original" hidden>匯出無法讀取的原始備份</button></div><p id="observation-status" class="hint"></p><ul id="observation-list" class="field-list"></ul></section></div><section class="panel"><h2>① 仰角與樹高</h2><label>角度來源<select id="angle-source"><option value="sensor">iPad 姿態感測器</option><option value="manual">外部量角器・手動輸入</option><option value="demo">教學模擬（不當作實測）</option></select></label><div id="sensor-controls"><button id="sensor-start" class="primary">啟用姿態感測器</button><button id="sensor-stop">停止</button><p id="sensor-status" class="hint" role="status">${window.isSecureContext?'需要使用者點選授權。':'目前不是安全連線，請使用 HTTPS 正式網址。'}</p><p class="hint">將後鏡頭朝向遠方、鏡頭視線保持水平且手持穩定，再校正零度；不是把 iPad 平放桌上。</p><button id="sensor-zero">以目前方向校正水平零度</button><p id="zero-status" class="hint">尚未校正</p><button id="sensor-lock">對準樹梢，鎖定穩定仰角</button><p id="sensor-stability" class="hint" aria-live="polite">等候讀值</p></div><div id="manual-controls" hidden><label>仰角 θ（°）<input id="manual-angle" type="number" min="1" max="80" step="0.1" value="45"></label><input id="angle-range" type="range" min="1" max="80" step="0.1" value="45" aria-label="調整手動或示範仰角"><label class="check"><input id="manual-confirm" type="checkbox">此角度已由外部觀測器讀取（模擬模式不需此項）</label></div><label>到樹幹的水平距離 D（m）<input id="field-distance" type="number" min="0.1" max="200" step="0.1" value="8"></label><p class="hint">用皮尺量水平距離，或先校正步長後計算；不使用 GPS 或加速度積分猜測距離。</p><label>鏡頭／觀測器中心離地 E（m）<input id="camera-height" type="number" min="0.1" max="3" step="0.01" value="1.3"></label><label class="check"><input id="distance-confirm" type="checkbox">距離與鏡頭高度已實際測量／校正</label><label class="check"><input id="ground-confirm" type="checkbox">站位與樹根近似等高，樹梢可清楚瞄準</label><div class="result" aria-live="polite"><span id="field-result-label">樹高估算</span><strong id="field-height">—</strong><p id="field-formula">H = D × tan(θ) + E</p></div><p id="field-error" class="error" role="alert"></p><button id="field-use" class="primary" disabled>② 帶入胸圍與碳儲量 →</button><p class="hint">一般式 H = D × tan(θ) + E。45° 時 tan(45°) = 1，回到等腰直角三角形特例 H = D + E。</p><details><summary>裝置能力與資料界線</summary><p>瀏覽器可讀姿態角度、在授權後使用相機。這不是雷射測距或 CO₂ 儀器，也未接入 LiDAR／AI 樹形辨識。相機畫面、感測器與照片不會上傳；本機儲存及 JSON 包含原始角度與方法，沒有照片內容。</p><p>瀏覽器與硬體能力不同。拒絕權限、沒有讀值或不支援時，可用外部量角器手動輸入。實際 iPad 精度仍需現場與已知角度比較。</p><a href="https://www.w3.org/TR/orientation-event/" target="_blank" rel="noopener">W3C 姿態規格 ↗</a></details><details><summary>分岔等特殊樹形為何需要複核？</summary><p>不同調查方法對低位分岔、胸高附近分岔、板根與傾斜幹的測量點有不同規定，不能自動合併胸圍或任意扣除樹洞體積。本版先保留現勘紀錄，不把特殊樹形套入單一正常樹幹模型，也不列入碳儲量總計。</p><a href="https://www.forest.gov.tw/file/203484" target="_blank" rel="noopener">林業署森林資源調查測量規則參考 ↗</a></details></section></div>`;
 $('#field-tree').value=selectedId||'';const selected=plants.find(p=>p.id===selectedId);if(selected)$('#observation-name').value=selected.label+' '+selected.species;
 $('#field-tree').onchange=()=>{const p=plants.find(p=>p.id===$('#field-tree').value);if(p)$('#observation-name').value=p.label+' '+p.species;};
 function source(){return $('#angle-source').value;}
 function condition(){return {inspected:$('#inspected').checked,flags:[...root.querySelectorAll('[name=condition]:checked')].map(e=>e.value),notes:$('#condition-notes').value.trim(),measurementHeight:Number($('#measurement-height').value)};}
 function instrument(){
  let angle,sensor=null;if(source()==='sensor'){if(!locked)throw Error('請先校正零度，並鎖定一組穩定的仰角。');angle=locked.angle;sensor=locked.sensor;}
  else angle=Number($('#manual-angle').value);
  return {distance:Number($('#field-distance').value),eye:Number($('#camera-height').value),angle,level:$('#ground-confirm').checked,aligned:source()==='sensor'?Boolean(locked):source()==='demo'||$('#manual-confirm').checked,calibrated:$('#distance-confirm').checked,source:source(),sensor,capturedAt:locked?.capturedAt||new Date().toISOString(),condition:condition()};
 }
 function review(){
  try{const r=conditionReview(condition());$('#condition-feedback').textContent=r.requiresReview?'待教師複核：'+r.warnings.join(' '):'已目視檢查且未勾選特殊樹形，可使用正常單幹的教學近似模型。這不是影像辨識結果。';return r;}catch(err){$('#condition-feedback').textContent=err.message;return {requiresReview:true};}
 }
 function update(){
  const r=review();$('#angle-kind').textContent=source()==='sensor'?'即時仰角':source()==='manual'?'手動仰角':'模擬仰角';if(source()!=='sensor')$('#live-angle').textContent=fmt(Number($('#manual-angle').value));$('#field-use').disabled=true;$('#field-result-label').textContent=source()==='demo'?'假想樹高・教學示範':'垂直樹高估算';
  let computed=false;try{const i=instrument(),g=clinometer(i);computed=true;$('#field-height').textContent=fmt(g.height)+' m';$('#field-formula').textContent=`H = ${fmt(i.distance)} × tan(${fmt(i.angle)}°) + ${fmt(i.eye)} = ${fmt(g.height)} m`;
   if(!g.valid)throw Error('請確認距離與鏡頭高度已測量、站位等高且角度已對準。');validateInstrument(i);if(r.requiresReview)throw Error('樹形待複核：可先儲存現勘紀錄，暫不帶入單幹碳儲量。');$('#field-error').textContent='';$('#field-use').disabled=false;
  }catch(err){$('#field-error').textContent=err.message;if(source()==='sensor'&&!locked)$('#field-height').textContent='待鎖定角度';else if(!computed)$('#field-height').textContent='請檢查輸入';}
 }
 function showPhoto(blob){if(photoUrl)URL.revokeObjectURL(photoUrl);photo=blob;photoUrl=URL.createObjectURL(blob);$('#photo-preview').src=photoUrl;$('#photo-area').hidden=false;}
 function saveBlob(name,blob){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function invalidate(){locked=null;$('#sensor-stability').textContent='讀值已清除，請重新對準並鎖定。';update();}
 $('#sensor-start').onclick=async()=>{zero=null;locked=null;$('#zero-status').textContent='尚未校正';update();try{$('#sensor-status').textContent='等候權限或有效讀值…';await hardware.startSensor((sample,samples)=>{if(disposed)return;const r=stableReading(samples,Date.now());$('#live-angle').textContent=fmt(sample.angle-(zero??0));$('#sensor-status').textContent='已收到感測器讀值（後鏡頭視線仰角）';$('#sensor-stability').textContent=`${r.stable?'讀值穩定':'保持穩定至少半秒'} · 波動 ${fmt(r.spread)}° · ${r.count} 筆${locked?' · 已鎖定 '+fmt(locked.angle)+'°':''}`;},message=>{if(!disposed)$('#sensor-status').textContent=message;});}catch(err){if(!disposed)$('#sensor-status').textContent=err.message;}};
 $('#sensor-stop').onclick=()=>{hardware.stopSensor();zero=null;$('#zero-status').textContent='感測器已停止，需重新校正';invalidate();$('#sensor-status').textContent='已停止感測器。';};
 $('#sensor-zero').onclick=()=>{const r=stableReading(hardware.samples,Date.now());if(!r.stable||Math.abs(r.mean)>20){toast('請讓後鏡頭視線指向水平遠方並保持穩定；校正偏移需在 ±20° 內。');return;}zero=r.mean;invalidate();$('#zero-status').textContent=`水平零度已校正（修正 ${fmt(zero)}°）`;};
 $('#sensor-lock').onclick=()=>{const r=stableReading(hardware.samples,Date.now());if(zero===null||!r.stable){toast('請先校正零度，再保持穩定半秒以上並鎖定。');return;}locked={angle:r.mean-zero,sensor:{zero,spread:r.spread,samples:hardware.samples.map(({beta,gamma,time})=>({beta,gamma,time}))},capturedAt:new Date().toISOString()};update();};
 $('#angle-source').onchange=()=>{hardware.stopSensor();zero=null;locked=null;$('#sensor-controls').hidden=source()!=='sensor';$('#manual-controls').hidden=source()==='sensor';$('#live-angle').textContent='—';$('#zero-status').textContent='尚未校正';update();};
 $('#manual-angle').oninput=()=>{$('#angle-range').value=$('#manual-angle').value;update();};$('#angle-range').oninput=()=>{$('#manual-angle').value=$('#angle-range').value;update();};
 for(const e of root.querySelectorAll('#field-distance,#camera-height,#distance-confirm,#ground-confirm,#manual-confirm,#inspected,[name=condition],#measurement-height,#condition-notes'))e.addEventListener('input',update);
 $('#camera-start').onclick=async()=>{try{$('#camera-status').textContent='等候後鏡頭權限…';const stream=await hardware.startCamera();if(!stream||disposed)return;$('#field-video').srcObject=stream;await $('#field-video').play();if(disposed)return;$('#camera-placeholder').hidden=true;$('#camera-status').textContent='後鏡頭已開啟；中心十字瞄準樹梢，仰角仍需由感測器校正並鎖定。';}catch{if(disposed)return;$('#camera-status').textContent='無法啟用後鏡頭（未授權、不支援或無後鏡頭）。可用照片選擇器留證；角度仍可手動輸入。';hardware.stopCamera();}};
 $('#camera-stop').onclick=()=>{hardware.stopCamera();$('#field-video').srcObject=null;$('#camera-placeholder').hidden=false;$('#camera-status').textContent='鏡頭已關閉。';};
 $('#take-photo').onclick=()=>{const v=$('#field-video');if(!hardware.stream||!v.videoWidth){toast('請先開啟後鏡頭，或用照片選擇器拍攝。');return;}const canvas=document.createElement('canvas');const scale=Math.min(1,1600/v.videoWidth);canvas.width=Math.round(v.videoWidth*scale);canvas.height=Math.round(v.videoHeight*scale);canvas.getContext('2d').drawImage(v,0,0,canvas.width,canvas.height);canvas.toBlob(b=>{if(b&&!disposed)showPhoto(b);},'image/jpeg',.85);};
 $('#photo-input').onchange=e=>{const f=e.target.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>10000000){toast('請選擇小於 10 MB 的 JPG、PNG 或 WebP。');e.target.value='';return;}showPhoto(f);e.target.value='';};
 $('#photo-preview').onerror=()=>{if(disposed)return;toast('照片無法解碼，請改用 JPG 或 PNG。');$('#photo-area').hidden=true;photo=null;if(photoUrl)URL.revokeObjectURL(photoUrl);photoUrl=null;};
 $('#photo-download').onclick=()=>{if(photo)saveBlob('校樹現勘照片.'+(photo.type==='image/png'?'png':photo.type==='image/webp'?'webp':'jpg'),photo);};
 $('#photo-remove').onclick=()=>{if(photoUrl)URL.revokeObjectURL(photoUrl);photo=null;photoUrl=null;$('#photo-preview').removeAttribute('src');$('#photo-area').hidden=true;};
 $('#field-use').onclick=()=>{try{const i=instrument();validateInstrument(i);if(conditionReview(i.condition).requiresReview)throw Error('特殊樹形待複核，先保留現勘紀錄。');onUse(i,{platformId:$('#field-tree').value,name:$('#observation-name').value.trim()});}catch(err){toast(err.message);}};
 function count(){ $('#observation-status').textContent=storageError?'舊現勘紀錄無法讀取，暫停新增以免覆寫；請先下載原始備份。':`本機現勘 ${observations.length} 筆。現勘紀錄不含 CO₂ 估值、不列入碳儲量統計；照片需另行下載。`;$('#export-original').hidden=!storageError;$('#observation-list').innerHTML=observations.slice(-10).reverse().map(o=>`<li>${esc(o.name)} · ${o.status==='requires_review'?'待教師複核':'已目視檢核'} · ${esc(o.createdAt)} · ${o.instrument?(o.instrument.source==='demo'?'教學模擬高度':o.instrument.source==='sensor'?'感測器高度':'外部量角器高度'):'尚無有效高度'}${o.photoRecorded?' · 照片另存':''}</li>`).join('');}
 $('#save-observation').onclick=()=>{if(storageError){toast('請先下載原始備份，勿覆寫舊資料。');return;}try{const c=condition(),r=conditionReview(c),name=$('#observation-name').value.trim();if(!name)throw Error('請填樹名或現勘編號。');if(observations.length>=300)throw Error('最多保存 300 筆現勘紀錄，請先匯出備份。');let i=null;try{const candidate=instrument();validateInstrument(candidate);i=candidate;}catch{/* Observations can be saved even before height measurement. */}const row={id:crypto.randomUUID(),name,platformId:$('#field-tree').value||null,createdAt:new Date().toISOString(),condition:c,status:r.requiresReview?'requires_review':'visually_checked',conditionDetection:'human_checklist',instrument:i,photoRecorded:Boolean(photo),photoIncluded:false,co2Kg:null};const next=[...observations,row];localStorage.setItem(KEY,JSON.stringify({version:1,type:'field_observations',observations:next}));observations=next;count();toast('現勘已存於這個瀏覽器；照片請另行下載。');}catch(err){toast(err.name==='QuotaExceededError'?'本機儲存空間不足，請先匯出現勘紀錄。':err.message);}};
 $('#export-observations').onclick=()=>saveBlob('校樹現勘紀錄.json',new Blob([JSON.stringify({version:1,type:'field_observations',observations},null,2)],{type:'application/json'}));
 $('#import-observations').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5000000)throw Error('檔案需小於 5 MB。');const next=parseObservations(await file.text());if(disposed)return;if(!await ask(`匯入 ${next.length} 筆並取代本機現勘紀錄？請先匯出備份。`))return;if(disposed)return;localStorage.setItem(KEY,JSON.stringify({version:1,type:'field_observations',observations:next}));observations=next;storageError=false;count();toast('已匯入現勘紀錄；照片需另外保管。');}catch(err){toast('匯入失敗：'+err.message);}finally{e.target.value='';}};
 $('#clear-observations').onclick=async()=>{if(!await ask('清除這個瀏覽器的所有現勘紀錄？請先匯出備份；碳儲量調查紀錄不受影響。'))return;if(disposed)return;try{localStorage.removeItem(KEY);observations=[];storageError=false;count();toast('已清除現勘紀錄。');}catch{toast('無法清除本機儲存。');}};
 $('#export-original').onclick=()=>{try{saveBlob('現勘原始備份.json',new Blob([localStorage.getItem(KEY)||''],{type:'application/json'}));}catch{toast('無法存取本機儲存。');}};
 const hidden=()=>{if(document.hidden){hardware.stop();zero=null;locked=null;$('#field-video').srcObject=null;$('#camera-placeholder').hidden=false;$('#sensor-status').textContent='背景時已停止感測與鏡頭，請重新啟用。';$('#zero-status').textContent='需重新校正';update();}};
 document.addEventListener('visibilitychange',hidden);count();update();
 return ()=>{disposed=true;hardware.stop();document.removeEventListener('visibilitychange',hidden);if(photoUrl)URL.revokeObjectURL(photoUrl);};
}
